
/* ==== styles.css ==== */
/* SDC V61 base reset */
:root{
  --sdc-bg:#eef2f6;
  --sdc-page:#f5f7fa;
  --sdc-surface:#ffffff;
  --sdc-surface-2:#f3f6f9;
  --sdc-soft:#e9eff5;
  --sdc-ink:#061522;
  --sdc-muted:#647285;
  --sdc-line:#d6dee8;
  --sdc-navy:#061522;
  --sdc-accent:#b91c2b;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
html,body{margin:0;min-height:100%;overflow-x:hidden;overflow-y:auto;touch-action:auto;-webkit-overflow-scrolling:touch;}
body{font-family:Barlow,system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;background:var(--sdc-page);color:var(--sdc-ink);}
button,input,select,textarea{font:inherit;}
button{cursor:pointer;border:0;}
.hide{display:none!important;}
.no-print{}
.boot-loading{min-height:100dvh;display:grid;place-items:center;padding:24px;background:var(--sdc-page);}
.boot-loading-card{width:min(360px,100%);padding:24px;border-radius:24px;border:1px solid var(--sdc-line);background:#fff;text-align:center;box-shadow:0 18px 44px rgba(6,21,34,.10);}
.boot-loading-card img{width:92px;height:92px;object-fit:contain;border-radius:20px;background:#fff;}
.boot-loading-card h1{margin:12px 0 4px;font-size:30px;color:var(--sdc-ink);}
.boot-loading-card p{margin:0;color:var(--sdc-muted);font-weight:800;}


