/* ==== css/sdc-v150-repair.css ==== */

/* SDC V150 · Reparación PC + móvil + secciones Inicio / Panel / Productos */
:root{
  --sdc-bg:#eef5fb;
  --sdc-card:#fff;
  --sdc-ink:#071625;
  --sdc-muted:#62748a;
  --sdc-line:#d7e6f5;
  --sdc-blue:#0b63ce;
  --sdc-navy:#061625;
  --sdc-red:#c81932;
  --sdc-green:#10b981;
  --sdc-shadow:0 18px 40px rgba(15,35,55,.08);
  --sdc-soft:0 10px 24px rgba(15,35,55,.06);
}
*{box-sizing:border-box}
html,body{max-width:100%;overflow-x:hidden!important}
body.sdc-v95-light-default{
  background:var(--sdc-bg)!important;
  color:var(--sdc-ink)!important;
}
body.sdc-v95-light-default #app.app{
  width:min(100vw - 28px,1760px)!important;
  max-width:1760px!important;
  margin:0 auto!important;
  padding:12px 0 36px!important;
  display:flex!important;
  flex-direction:column!important;
  gap:16px!important;
}
@media(min-width:1500px){
  body.sdc-v95-light-default #app.app{width:calc(100vw - 52px)!important;max-width:1900px!important}
}

/* Top */
body.sdc-v95-light-default .sdc-utility-tabs-v105{
  width:min(100vw - 28px,1760px)!important;
  max-width:1760px!important;
  margin:10px auto 12px!important;
  display:grid!important;
  grid-template-columns:minmax(180px,.8fr) minmax(260px,1.2fr)!important;
  gap:12px!important;
}
body.sdc-v95-light-default .sdc-utility-tabs-v105 button{
  min-height:54px!important;
  border-radius:18px!important;
  border:1px solid var(--sdc-line)!important;
  font-weight:950!important;
  letter-spacing:.04em!important;
}
body.sdc-v95-light-default .sdc-utility-tabs-v105 button:last-child{
  color:#fff!important;
  border:none!important;
  background:linear-gradient(135deg,var(--sdc-navy),var(--sdc-blue),var(--sdc-green))!important;
}
body.sdc-v95-light-default .topbar{
  width:100%!important;
  display:grid!important;
  grid-template-columns:auto minmax(0,1fr) auto!important;
  gap:16px!important;
  align-items:center!important;
  padding:20px!important;
  border:1px solid var(--sdc-line)!important;
  border-radius:26px!important;
  background:#fff!important;
  box-shadow:var(--sdc-soft)!important;
}
body.sdc-v95-light-default .topbar .spacer{display:none!important}
body.sdc-v95-light-default .top-logo{width:64px!important;height:64px!important;border-radius:18px!important;object-fit:contain!important}
body.sdc-v95-light-default .top-title h1{font-size:42px!important;line-height:.95!important;margin:0!important}
body.sdc-v95-light-default .top-title small, 
body.sdc-v95-light-default .top-meta-v88{display:block!important;color:#50647b!important;font-weight:900!important}

/* Tabs */
body.sdc-v95-light-default .sdc-tabs-v150{
  display:grid!important;
  grid-template-columns:repeat(3,minmax(0,1fr))!important;
  gap:8px!important;
  padding:7px!important;
  border-radius:24px!important;
  background:#fff!important;
  border:1px solid var(--sdc-line)!important;
  box-shadow:var(--sdc-soft)!important;
}
body.sdc-v95-light-default .sdc-tabs-v150 button{
  min-height:62px!important;
  border:0!important;
  border-radius:19px!important;
  background:#f4f8fc!important;
  color:#334155!important;
  display:flex!important;
  gap:10px!important;
  align-items:center!important;
  justify-content:center!important;
  font-family:'Chakra Petch',sans-serif!important;
  font-weight:950!important;
  font-size:18px!important;
  letter-spacing:.06em!important;
  text-transform:uppercase!important;
}
body.sdc-v95-light-default .sdc-tabs-v150 button.active{
  color:#fff!important;
  background:linear-gradient(135deg,var(--sdc-navy),var(--sdc-blue))!important;
  box-shadow:0 12px 26px rgba(11,99,206,.25)!important;
}

/* Page show/hide */
body[data-sdc-page-v150="inicio"] .panel-v150,
body[data-sdc-page-v150="inicio"] #inventario{display:none!important}
body[data-sdc-page-v150="panel"] .home-hero-v94,
body[data-sdc-page-v150="panel"] #inventario{display:none!important}
body[data-sdc-page-v150="productos"] .home-hero-v94,
body[data-sdc-page-v150="productos"] .panel-v150{display:none!important}
body[data-sdc-page-v150="productos"] #inventario{display:block!important}

/* Inicio */
