body.sdc-v95-light-default .home-sync-row-v94 span{display:inline-flex!important;gap:5px!important;align-items:center!important;padding:9px 14px!important;border-radius:999px!important;background:#f4f9ff!important;border:1px solid var(--sdc-line)!important}
