/* ==== css/sdc-v177-full-structure.css ==== */
/* SDC V177 · estructura nueva completa para móvil y GitHub Pages */
:root{
  --sdc177-bg:#f3f7fc;
  --sdc177-card:#ffffff;
  --sdc177-ink:#071326;
  --sdc177-muted:#687b95;
  --sdc177-line:#dfe8f4;
  --sdc177-line2:#edf3fa;
  --sdc177-blue:#0d6df2;
  --sdc177-purple:#7a2cff;
  --sdc177-violet:#9b22e6;
  --sdc177-navy:#06172d;
  --sdc177-green:#10b981;
  --sdc177-shadow:0 18px 46px rgba(15,23,42,.075);
  --sdc177-soft:0 10px 24px rgba(15,23,42,.055);
}
html,body{background:radial-gradient(circle at top left,rgba(122,44,255,.10),transparent 32%),linear-gradient(180deg,#f8fbff 0%,var(--sdc177-bg) 100%)!important;color:var(--sdc177-ink)!important;}
body.sdc-v95-light-default #app.app{width:min(100% - 18px,960px)!important;max-width:960px!important;padding:12px 0 34px!important;gap:12px!important;}
body.sdc-v95-light-default img{max-width:100%;}
body.sdc-v95-light-default .sdc-menu-fab-v116{display:none!important;}

/* Header nuevo: ya no usa la estructura vieja comprimida */
body.sdc-v95-light-default .sdc-shell-top-v177{display:grid!important;gap:12px!important;}
body.sdc-v95-light-default .sdc-action-row-v177{display:grid!important;grid-template-columns:1fr 1fr!important;gap:10px!important;align-items:center!important;}
body.sdc-v95-light-default .sdc-menu-main-v177,
body.sdc-v95-light-default .sdc-sync-main-v177{min-height:58px!important;border-radius:24px!important;border:1px solid var(--sdc177-line)!important;box-shadow:var(--sdc177-soft)!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:12px!important;font-weight:950!important;letter-spacing:.01em!important;white-space:nowrap!important;}
body.sdc-v95-light-default .sdc-menu-main-v177{background:#fff!important;color:#071326!important;}
body.sdc-v95-light-default .sdc-sync-main-v177{background:linear-gradient(135deg,var(--sdc177-purple),var(--sdc177-blue))!important;color:#fff!important;border-color:transparent!important;}
body.sdc-v95-light-default .sdc-sync-main-v177 span{font-size:24px!important;line-height:1!important;}
body.sdc-v95-light-default .sdc-burger-v177{width:25px;height:18px;display:inline-block;position:relative;}
body.sdc-v95-light-default .sdc-burger-v177::before,
body.sdc-v95-light-default .sdc-burger-v177::after,
body.sdc-v95-light-default .sdc-burger-v177{border-top:3px solid currentColor;}
body.sdc-v95-light-default .sdc-burger-v177::before,
body.sdc-v95-light-default .sdc-burger-v177::after{content:"";position:absolute;left:0;width:25px;border-radius:999px;}
body.sdc-v95-light-default .sdc-burger-v177::before{top:5px;}
body.sdc-v95-light-default .sdc-burger-v177::after{top:13px;}

body.sdc-v95-light-default .sdc-brand-card-v177{position:relative;overflow:hidden;display:grid!important;grid-template-columns:76px minmax(0,1fr)!important;gap:14px!important;align-items:center!important;background:rgba(255,255,255,.92)!important;border:1px solid var(--sdc177-line)!important;border-radius:28px!important;box-shadow:var(--sdc177-shadow)!important;padding:16px!important;}
body.sdc-v95-light-default .sdc-brand-card-v177::before{content:"";position:absolute;inset:0 auto 0 0;width:5px;background:linear-gradient(180deg,var(--sdc177-purple),var(--sdc177-blue));}
body.sdc-v95-light-default .sdc-brand-card-v177::after{content:"";position:absolute;right:-90px;top:-100px;width:220px;height:220px;background:radial-gradient(circle,rgba(13,109,242,.13),transparent 70%);pointer-events:none;}
body.sdc-v95-light-default .sdc-brand-logo-v177{width:74px;height:74px;border-radius:24px;background:#fff;border:1px solid var(--sdc177-line);box-shadow:0 10px 26px rgba(15,23,42,.08);display:grid;place-items:center;padding:7px;position:relative;z-index:1;}
body.sdc-v95-light-default .sdc-brand-logo-v177 img{width:100%;height:100%;object-fit:contain;border-radius:18px;}
body.sdc-v95-light-default .sdc-brand-copy-v177{min-width:0;position:relative;z-index:1;}
