body.sdc-v95-light-default .sdc-brand-copy-v177 span{width:max-content;max-width:100%;display:inline-flex;align-items:center;gap:8px;min-height:31px;padding:7px 11px;border-radius:999px;background:#edf4ff;color:#1d5ee8;border:1px solid #d8e6ff;font-weight:950;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
body.sdc-v95-light-default .sdc-brand-copy-v177 i{font-style:normal;}

/* Navegación real tipo app */
body.sdc-v95-light-default .sdc-tabs-v177{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:0!important;padding:7px!important;background:#fff!important;border:1px solid var(--sdc177-line)!important;border-radius:26px!important;box-shadow:var(--sdc177-soft)!important;overflow:hidden!important;}
body.sdc-v95-light-default .sdc-tabs-v177 button{min-height:64px!important;border-radius:20px!important;background:transparent!important;color:#6c7b91!important;font-size:15px!important;font-weight:900!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:8px!important;position:relative!important;}
