body.sdc-v95-light-default .sdc-tabs-v177 button.active::before{display:none!important;}
body.sdc-v95-light-default .sdc-tabs-v177 i{font-style:normal!important;font-size:18px!important;opacity:.95;}

/* Productos: sección completamente nueva, sin la caja vieja */
body.sdc-v95-light-default[data-sdc-page-v150="productos"] #inventario{display:block!important;background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;border-radius:0!important;}
