body.sdc-v95-light-default .products-hero-v177::after{content:"";position:absolute;right:-70px;bottom:-90px;width:230px;height:230px;border-radius:50%;background:radial-gradient(circle,rgba(122,44,255,.13),transparent 68%);pointer-events:none;}
