body.sdc-v95-light-default .products-kicker-v177{display:inline-flex;width:max-content;max-width:100%;margin:0 0 12px;padding:8px 14px;border-radius:999px;background:#f1e9ff;border:1px solid #dfd0ff;color:#7334d8;text-transform:uppercase;font-size:12px;font-weight:950;letter-spacing:.055em;}
