  --sdc178-ink:#071a35;
  --sdc178-muted:#64748b;
  --sdc178-soft:#eff7ff;
  --sdc178-soft2:#f7fbff;
  --sdc178-line:#d7e6f8;
  --sdc178-line2:#e6f0fb;
  --sdc178-blue:#0877ff;
  --sdc178-blue2:#005bd8;
  --sdc178-cyan:#38bdf8;
  --sdc178-navy:#061a33;
  --sdc178-navy2:#0a2a52;
  --sdc178-green:#10b981;
  --sdc178-orange:#f59e0b;
  --sdc178-red:#e11d48;
  --sdc177-purple:#0877ff;
  --sdc177-violet:#0b63ce;
  --sdc-v176-purple:#0877ff;
  --sdc-v176-purple-2:#0b63ce;
  --sdc178-shadow:0 18px 46px rgba(6,26,51,.11);
  --sdc178-softshadow:0 10px 24px rgba(6,26,51,.075);
}
html,body{
  background:
    radial-gradient(circle at 16% -10%,rgba(8,119,255,.18),transparent 30%),
    radial-gradient(circle at 120% 6%,rgba(56,189,248,.14),transparent 28%),
    linear-gradient(180deg,#f8fcff 0%,var(--sdc178-bg) 100%)!important;
  color:var(--sdc178-ink)!important;
}
body.sdc-v95-light-default #app.app{
  width:min(100% - 18px,460px)!important;
  max-width:460px!important;
  margin:0 auto!important;
  padding:12px 0 42px!important;
  gap:12px!important;
}
