  --sdc179-soft:0 16px 34px rgba(5,39,89,.08);
}

body.sdc-v95-light-default .sdc-menu-backdrop-v116{
  position:fixed!important;
  inset:0!important;
  display:block!important;
  opacity:0!important;
  pointer-events:none!important;
  background:radial-gradient(circle at 12% 8%, rgba(8,119,255,.20), transparent 26%), rgba(2,8,18,.68)!important;
  backdrop-filter:blur(8px)!important;
  -webkit-backdrop-filter:blur(8px)!important;
  z-index:7000!important;
  transition:opacity .22s ease!important;
}
body.sdc-v95-light-default.sdc-menu-open-v116 .sdc-menu-backdrop-v116{
  opacity:1!important;
  pointer-events:auto!important;
}

body.sdc-v95-light-default .sdc-menu-drawer-v116,
body.sdc-v95-light-default .sdc-menu-drawer-v179{
  position:fixed!important;
