/* ==== css/sdc-v207-s24-ultra-pro.css ==== */

/* =========================================================
   SD Comayagua · v207 S24 Ultra Mobile Pro
   Enfoque: Galaxy S24 Ultra / móvil alto.
   Corrige: lectura, scroll, acciones, modales, cotización,
   recibos, productos, inputs y cortes visuales.
   ========================================================= */

:root{
  --sdc207-blue:#0b63ce;
  --sdc207-blue2:#0877f2;
  --sdc207-ink:#07192f;
  --sdc207-muted:#647891;
  --sdc207-line:#d8e7f6;
  --sdc207-soft:#f4f9ff;
  --sdc207-card:#ffffff;
  --sdc207-radius:24px;
}

/* Base móvil: no más scroll horizontal ni cortes raros */
html,
body{
  max-width:100%!important;
  overflow-x:hidden!important;
  overscroll-behavior-y:contain!important;
  -webkit-text-size-adjust:100%!important;
  text-rendering:optimizeLegibility!important;
}
body.sdc-v95-light-default{
  background:
    radial-gradient(circle at 15% 0%, rgba(73,172,255,.18), transparent 34%),
    linear-gradient(180deg,#edf6ff 0%,#f8fbff 56%,#eef5fb 100%)!important;
}
body.sdc-v95-light-default *{
  box-sizing:border-box!important;
  -webkit-tap-highlight-color:rgba(11,99,206,.12)!important;
}
body.sdc-v95-light-default img{
  max-width:100%!important;
}
body.sdc-v95-light-default input,
body.sdc-v95-light-default select,
body.sdc-v95-light-default textarea,
body.sdc-v95-light-default button{
  font:inherit!important;
}

/* App centrada y optimizada para ancho CSS real del S24 Ultra */
body.sdc-v95-light-default #app.app,
body.sdc-v95-light-default #app{
  width:min(100% - 14px,462px)!important;
  max-width:462px!important;
  margin:0 auto!important;
  padding-bottom:calc(34px + env(safe-area-inset-bottom,0px))!important;
}

/* Cuando se abre desde computadora, mantiene marco móvil pero sin sentirse roto */
@media(min-width:760px){
  body.sdc-v95-light-default #app.app,
  body.sdc-v95-light-default #app{
    width:min(100% - 24px,462px)!important;
  }
}

/* Tarjetas principales más limpias y respirables */
body.sdc-v95-light-default .sdc-hero-v178,
body.sdc-v95-light-default .catalog-cover-v178,
body.sdc-v95-light-default .catalog-control-v178,
body.sdc-v95-light-default .home-stats,
body.sdc-v95-light-default .stats,
body.sdc-v95-light-default .panel-card,
body.sdc-v95-light-default .card-box{
  border-radius:28px!important;
  border-color:rgba(216,231,246,.96)!important;
  box-shadow:0 18px 46px rgba(7,26,53,.08)!important;
}

/* Metrícas: evita que Lps. se corte o se apachurre */
