:root{
  --sdc231-ink:#07192f;
  --sdc231-ink-2:#16324f;
  --sdc231-muted:#61788f;
  --sdc231-line:#d9e8f8;
  --sdc231-soft:#f5f9ff;
  --sdc231-card:#ffffff;
  --sdc231-navy:#071a35;
  --sdc231-blue:#0b63ce;
  --sdc231-blue-2:#1687ff;
  --sdc231-green:#18a76f;
  --sdc231-danger:#dd385c;
  --sdc231-warning:#f59e0b;
  --sdc231-radius:24px;
  --sdc231-shadow:0 18px 46px rgba(7,26,53,.09);
  --sdc231-shadow-soft:0 12px 28px rgba(7,26,53,.065);
  --sdc231-page:max(12px, env(safe-area-inset-left));
}

html{
  min-width:320px!important;
