/* ==== css/sdc-v232-category-clean.css ==== */
/* SD Comayagua · v232
   Corrección: al usar CATEGORÍA en Catálogo no debe aparecer el Panel privado
   con métricas de inversión/ganancia. Esta capa restaura la separación real
   entre Inicio, Panel y Productos después de los estilos responsive v231. */

/* INICIO: solo dashboard de inicio */
body[data-sdc-page-v150="inicio"] .panel-v150,
body[data-sdc-page-v150="inicio"] #inventario{
  display:none!important;
}

/* PANEL: solo resumen privado / inversión */
body[data-sdc-page-v150="panel"] .home-hero-v94,
body[data-sdc-page-v150="panel"] .sdc209-home,
body[data-sdc-page-v150="panel"] #inventario{
  display:none!important;
}
body[data-sdc-page-v150="panel"] .panel-v150{
  display:grid!important;
}

/* PRODUCTOS / CATÁLOGO: nunca mostrar el panel privado al filtrar categoría */
body[data-sdc-page-v150="productos"] .home-hero-v94,
body[data-sdc-page-v150="productos"] .sdc209-home,
body[data-sdc-page-v150="productos"] .panel-v150{
  display:none!important;
}
body[data-sdc-page-v150="productos"] #inventario{
  display:block!important;
}

/* Limpieza visual del catálogo cuando se filtra desde Categorías */
body[data-sdc-page-v150="productos"] #inventario{
  margin-top:0!important;
}
body[data-sdc-page-v150="productos"] .inventory-content{
  margin-top:clamp(10px,1.6vw,18px)!important;
}

/* En celular, evitar que tarjetas privadas reaparezcan por reglas antiguas */
@media (max-width:760px){
  body[data-sdc-page-v150="productos"] .panel-v150,
  body.sdc-v231-quality[data-sdc-page-v150="productos"] .panel-v150,
  body.sdc-v95-light-default[data-sdc-page-v150="productos"] .panel-v150{
    display:none!important;
  }
  body[data-sdc-page-v150="productos"] #inventario,
  body.sdc-v231-quality[data-sdc-page-v150="productos"] #inventario,
  body.sdc-v95-light-default[data-sdc-page-v150="productos"] #inventario{
    display:block!important;
  }
}


